// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Result/** * NOUS — Agentic tool interface. * * A tool is anything the LLM can invoke during a ReAct workflow: *   - Call a skill (CallSkill, SmsSkill, OpenAppSkill, ...) *   - Search the web *   - Fetch + parse a URL *   - Recall a memory *   - Query the knowledge graph *   - Run a shell command (sideload only) * * Tools are registered in [AgenticToolRegistry]. The LLM sees the tool's * [id], [displayName], [description], and [paramSchema] — it uses these to * decide when to call the tool and what parameters to pass. * * ## Tool vs Skill * *   - **Skill** — invoked directly by [com.roshan.persona.brain.skill.SkillRouter] *     when an intent matches. Synchronous, single-call. *   - **Tool** — invoked by the LLM during an agentic workflow. May be called *     multiple times in one workflow. Returns an observation the LLM reasons about. * * Most skills are also exposed as tools (via [SkillAsToolAdapter]), but not * all tools are skills (e.g., "search_web" is a tool but not a skill). * * ## Privacy * *   - Tool [description] and [paramSchema] are sent to the LLM (needed for *     the LLM to know how to use the tool). *   - Tool parameters may contain user data — tools must NOT log or transmit *     params unless explicitly required (and only to the tool's own endpoint). *   - Tools that make network calls must respect [BrainContext.budget.allowCloud]. * * @see <a href="docs/spec/module2-spec-review.pdf">§9.3 Tools</a> */interface AgenticTool {    /** Unique tool ID (e.g., "search_web", "fetch_url", "call_skill:send_sms"). */    val id: String    /** Human-readable name (shown to LLM in tool catalog). */    val displayName: String    /** What this tool does (LLM reads this to decide when to call it). */    val description: String    /** Parameter schema — describes what params the tool accepts. */    val paramSchema: List<ToolParam>    /** Whether this tool requires cloud/network access. */    val requiresNetwork: Boolean    /**     * Execute the tool with [params].     *     * @param params tool-specific parameters (validated against [paramSchema])     * @param context the brain context (for persona, budget, dispatchers)     * @return [AgenticStepResult.ToolSuccess] or [AgenticStepResult.ToolFailure]     */    suspend fun execute(        params: Map<String, String>,        context: BrainContext,    ): AgenticStepResult}/** * Describes one parameter that a tool accepts. * * The LLM sees this schema to know what params to pass. Used for validation * before the tool is actually invoked. */data class ToolParam(    /** Parameter name (e.g., "query", "url", "contact"). */    val name: String,    /** Human-readable description (LLM reads this). */    val description: String,    /** Whether this param is required. */    val required: Boolean,    /** Example value (helps LLM understand format). */    val example: String? = null,    /** Allowed values (for enum-like params). Empty = any string. */    val allowedValues: Set<String> = emptySet(),) {    init {        require(name.isNotBlank()) { "Param name cannot be blank" }        require(description.isNotBlank()) { "Param description cannot be blank" }    }}/** * NOUS — Agentic tool registry. * * Holds all tools available to the LLM during a ReAct workflow. The * [AgenticPlanner] queries this to build the tool catalog sent to the LLM. * * Tools are registered via [register]. Built-in tools are auto-registered * in [BuiltInAgenticTools]. * * ## Hilt Integration * * In Module 9, tools are registered via Hilt multibinding: * ```kotlin * @Binds @IntoSet * abstract fun bindWebSearchTool(impl: WebSearchTool): AgenticTool * ``` * The registry collects all `Set<AgenticTool>` from Hilt automatically. * * @see <a href="docs/spec/module2-spec-review.pdf">§9.3.1 Tool Registry</a> */class AgenticToolRegistry {    private val toolsById = java.util.concurrent.ConcurrentHashMap<String, AgenticTool>()    /**     * Register a tool. Replaces any existing tool with the same ID.     */    fun register(tool: AgenticTool) {        toolsById[tool.id] = tool    }    /**     * Register multiple tools at once.     */    fun registerAll(tools: Collection<AgenticTool>) {        for (tool in tools) {            register(tool)        }    }    /**     * Get a tool by ID.     */    fun getById(id: String): AgenticTool? = toolsById[id]    /**     * Get all registered tools.     */    fun getAll(): List<AgenticTool> = toolsById.values.toList().sortedBy { it.id }    /**     * Get tools that don't require network (for offline workflows).     */    fun getOfflineTools(): List<AgenticTool> = getAll().filter { !it.requiresNetwork }    /**     * Validate [params] against the tool's [AgenticTool.paramSchema].     *     * @return null if valid, or an error message string if invalid     */    fun validateParams(toolId: String, params: Map<String, String>): String? {        val tool = toolsById[toolId]            ?: return "Unknown tool: $toolId"        // Check required params        for (param in tool.paramSchema.filter { it.required }) {            val value = params[param.name]            if (value.isNullOrBlank()) {                return "Missing required parameter: ${param.name}"            }        }        // Check allowed values        for (param in tool.paramSchema) {            val value = params[param.name] ?: continue            if (param.allowedValues.isNotEmpty() && value !in param.allowedValues) {                return "Parameter '${param.name}' must be one of: ${param.allowedValues.joinToString(", ")}"            }        }        return null    }    /**     * Number of registered tools.     */    fun size(): Int = toolsById.size}